import { MODELO_PUBLICACION, MODELO_EDITORIAL, TABLA_PUBLICACIONES } from '../../models/editorial-publicacion.model.mjs';

export async function trasladarPublicacionRepository(publicacionId, editorialId) {
  const { Attributes } = await MODELO_PUBLICACION.build(UpdateItemCommand)
    .item({ publicacionId, editorialId })
    .options({
      condition: { attr: 'publicacionId', exists: true },
      returnValues: 'ALL_NEW'
    })
    .send();
  return Attributes;
}

import { consultarEditorialService } from './service.mjs';

export async function handler(event) {
  const editorialId = Number(event.pathParameters.editorialId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarEditorialService(editorialId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarEditorialRepository, consultarEditorialRepository } from './repository.mjs';

export async function consultarEditorialService(editorialId, minimo) {
  const editorial = await buscarEditorialRepository(editorialId);
  if (!editorial) throw new Error('Editorial no encontrado');
  const publicaciones = await consultarEditorialRepository(editorialId, minimo);
  return { editorial, publicaciones };
}

import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_PUBLICACION, MODELO_EDITORIAL, TABLA_PUBLICACIONES } from '../../models/editorial-publicacion.model.mjs';

export async function buscarEditorialRepository(editorialId) {
  const { Item } = await MODELO_EDITORIAL.build(GetItemCommand)
    .key({ editorialId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEditorialRepository(editorialId, minimo) {
  const { Items = [] } = await TABLA_PUBLICACIONES.build(QueryCommand)
    .entities(MODELO_PUBLICACION)
    .query({ index: 'PorEditorial', partition: editorialId })
    .options({ filters: { Publicacion: { attr: 'paginas', gte: minimo } } })
    .send();
  return Items;
}
